<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse; use Illuminate\Http\RedirectResponse; use Illuminate\Support\Facades\DB; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Models\Node; use Pterodactyl\Models\Allocation; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Allocations\AssignmentService; use Pterodactyl\Services\Dezerx\Allocations\PortCatalogue; use Pterodactyl\Services\Dezerx\Allocations\AllocationFolders; class AllocationToolsController extends Controller { public function __construct( private AlertsMessageBag $alert, private AssignmentService $assignmentService, ) { } public function scan(Request $request, Node $node): JsonResponse { $rows = $this->rows($node); $sorted = PortCatalogue::read($rows); $saved = AllocationFolders::node($node->id); $already = []; foreach ($saved['folders'] as $folder) { $profile = $saved['meta'][$folder['id']]['profile'] ?? ''; if ($profile !== '') { $already[$profile] = array_flip($folder['allocations']); } } $groups = []; $total = 0; foreach ($sorted as $key => $ids) { $profile = PortCatalogue::profile($key); $fresh = array_values(array_diff($ids, array_keys($already[$key] ?? []))); $ports = Allocation::query() ->where('node_id', $node->id) ->whereIn('id', array_slice($ids, 0, 6)) ->orderBy('port') ->pluck('port') ->all(); $groups[] = [ 'key' => $key, 'name' => $profile['name'], 'icon' => $profile['icon'], 'color' => $profile['color'], 'blurb' => $profile['blurb'], 'count' => count($ids), 'moving' => count($fresh), 'filed' => isset($already[$key]), 'sample' => $ports, ]; $total += count($fresh); } return new JsonResponse([ 'groups' => $groups, 'moving' => $total, 'scanned' => Allocation::query()->where('node_id', $node->id)->count(), 'review' => PortCatalogue::review($rows), ]); } public function sort(Request $request, Node $node): RedirectResponse { $data = $request->validate([ 'groups' => ['required', 'array'], 'groups.*' => ['string', 'max:64'], ]); $wanted = array_flip($data['groups']); $sorted = array_intersect_key(PortCatalogue::read($this->rows($node)), $wanted); $done = AllocationFolders::file($node->id, $sorted); if ($done === []) { $this->alert->info('Nothing needed moving. Those allocations are already where the sorter would put them.')->flash(); } else { $moved = array_sum($done); $names = array_map( fn (string $key) => PortCatalogue::profile($key)['name'] ?? $key, array_keys($done), ); $this->alert->success(sprintf( 'Sorted %s allocation%s into %s. Nothing about the allocations themselves was changed.', number_format($moved), $moved === 1 ? '' : 's', $this->list($names), ))->flash(); } return $this->back($request, $node); } public function plan(Request $request, Node $node): JsonResponse { $data = $this->planning($request); $plan = PortCatalogue::plan( $data['profile'], $data['servers'], $data['start'], $data['extras'], $this->taken($node, $data['ip']), ); return new JsonResponse($plan + [ 'ip' => $data['ip'], 'array' => PortCatalogue::portArray( $data['profile'], $data['start'], $data['extras'], $data['ip'], ), ]); } public function create(Request $request, Node $node): RedirectResponse { $data = $this->planning($request); $plan = PortCatalogue::plan( $data['profile'], $data['servers'], $data['start'], $data['extras'], $this->taken($node, $data['ip']), ); if (isset($plan['error']) || $plan['blocks'] === []) { $this->alert->danger($plan['error'] ?? 'There was nothing in that plan to create.')->flash(); return $this->back($request, $node); } if ($plan['over']) { $this->alert->danger(sprintf( 'That plan is %s new ports, which is over the %s a single run will create. Do it in a couple of passes.', number_format($plan['fresh']), number_format($plan['limit']), ))->flash(); return $this->back($request, $node); } $before = (int) Allocation::query()->where('node_id', $node->id)->max('id'); try { $this->assignmentService->handle($node, [ 'allocation_ip' => $data['ip'], 'allocation_alias' => $data['alias'], 'allocation_ports' => PortCatalogue::ranges($plan), ]); } catch (\Exception $exception) { $this->alert->danger('Nothing was created: ' . $exception->getMessage())->flash(); return $this->back($request, $node); } $created = Allocation::query() ->where('node_id', $node->id) ->where('id', '>', $before) ->pluck('id') ->map(fn ($id) => (int) $id) ->all(); if ($created === []) { $this->alert->info(sprintf( 'Nothing was created. Every port in that plan is already on %s.', $data['ip'], ))->flash(); return $this->back($request, $node); } $folder = $data['folder'] === '' || $data['folder'] === AllocationFolders::ALL ? AllocationFolders::ensure($node->id, $data['profile']) : $data['folder']; AllocationFolders::move($node->id, $folder, $created); $this->alert->success(sprintf( 'Created %s allocation%s for %s on %s%s, and filed %s into "%s".', number_format(count($created)), count($created) === 1 ? '' : 's', $plan['name'], $data['ip'], $plan['existing'] > 0 ? sprintf(' (%s port%s were already there)', number_format($plan['existing']), $plan['existing'] === 1 ? '' : 's') : '', count($created) === 1 ? 'it' : 'them', AllocationFolders::label($node->id, $folder) ?? $plan['name'], ))->flash(); return redirect()->route('admin.nodes.view.allocation', [ 'node' => $node->id, 'folder' => $folder, ]); } public function purge(Request $request, Node $node): RedirectResponse { $data = $request->validate([ 'port_from' => ['required', 'integer', 'min:1', 'max:65535'], 'port_to' => ['required', 'integer', 'min:1', 'max:65535'], 'ip' => ['nullable', 'string', 'max:191'], 'folder' => ['nullable', 'string', 'max:64'], ]); $low = min($data['port_from'], $data['port_to']); $high = max($data['port_from'], $data['port_to']); $query = Allocation::query() ->where('node_id', $node->id) ->whereBetween('port', [$low, $high]) ->when(!empty($data['ip']), fn ($inner) => $inner->where('ip', $data['ip'])); $folder = (string) ($data['folder'] ?? AllocationFolders::ALL); if (AllocationFolders::enabled() && $folder !== '' && $folder !== AllocationFolders::ALL) { AllocationFolders::narrow($query, $node->id, $folder); } $held = (clone $query)->whereNotNull('server_id')->count(); $taken = (clone $query)->whereNull('server_id')->count(); if ($taken === 0) { $this->alert->info(sprintf( 'Nothing to delete between %d and %d%s.', $low, $high, $held > 0 ? sprintf('; all %s there are in use by a server', number_format($held)) : '', ))->flash(); return $this->back($request, $node); } $query->whereNull('server_id')->delete(); $this->alert->success(sprintf( 'Deleted %s allocation%s between %d and %d%s.', number_format($taken), $taken === 1 ? '' : 's', $low, $high, $held > 0 ? sprintf('. %s in that range belong to a server and were left alone', number_format($held)) : '', ))->flash(); return $this->back($request, $node); } private function rows(Node $node): array { return DB::table('allocations') ->leftJoin('servers', 'servers.id', '=', 'allocations.server_id') ->leftJoin('eggs', 'eggs.id', '=', 'servers.egg_id') ->leftJoin('nests', 'nests.id', '=', 'eggs.nest_id') ->where('allocations.node_id', $node->id) ->select([ 'allocations.id', 'allocations.port', 'allocations.server_id', 'servers.name as server_name', 'eggs.name as egg', 'nests.name as nest', ]) ->get() ->map(fn ($row) => (array) $row) ->all(); } private function taken(Node $node, string $ip): array { return array_flip( Allocation::query() ->where('node_id', $node->id) ->where('ip', $ip) ->pluck('port') ->map(fn ($port) => (int) $port) ->all(), ); } private function planning(Request $request): array { $data = $request->validate([ 'profile' => ['required', 'string', 'max:64'], 'ip' => ['required', 'string', 'max:191'], 'servers' => ['required', 'integer', 'min:1', 'max:2000'], 'start' => ['required', 'integer', 'min:1025', 'max:65535'], 'alias' => ['nullable', 'string', 'max:191'], 'folder' => ['nullable', 'string', 'max:64'], 'extras' => ['nullable', 'array'], 'extras.*' => ['integer', 'min:1025', 'max:65535'], ]); return [ 'profile' => $data['profile'], 'ip' => trim($data['ip']), 'servers' => (int) $data['servers'], 'start' => (int) $data['start'], 'alias' => $data['alias'] ?? null, 'folder' => (string) ($data['folder'] ?? ''), 'extras' => array_map('intval', (array) ($data['extras'] ?? [])), ]; } private function back(Request $request, Node $node): RedirectResponse { $folder = (string) $request->input('current', AllocationFolders::ALL); return redirect()->route('admin.nodes.view.allocation', [ 'node' => $node->id, 'folder' => $folder === '' ? AllocationFolders::ALL : $folder, ]); } private function list(array $names): string { if (count($names) === 1) { return $names[0]; } $last = array_pop($names); return implode(', ', $names) . ' and ' . $last; } } 